public static void main(Args _args)
{
    ABSMRPAssessmentReportController controller = new ABSMRPAssessmentReportController();
    controller.parmReportName(ssrsReportStr(ABSMRPAssessmentReport, Report));
    controller.parmArgs(_args);
    controller.startOperation();
}

protected void prePromptModifyContract()
{
    ABSMRPAssessmentReportContract  contract;
    ABSMRPAssessmentRun             run;
    Args                            lArgs = this.parmArgs();

    super();

    if (lArgs && lArgs.record() && lArgs.dataset() == tableNum(ABSMRPAssessmentRun))
    {
        run      = lArgs.record();
        contract = this.parmReportContract().parmRdpContract() as ABSMRPAssessmentReportContract;
        if (contract)
        {
            contract.parmRunId(run.RunId);
        }
    }
}

protected void preRunModifyContract()
{
    ABSMRPAssessmentReportContract  contract;
    ABSMRPAssessmentRun             run;
    Args                            lArgs = this.parmArgs();

    super();

    if (lArgs && lArgs.record() && lArgs.dataset() == tableNum(ABSMRPAssessmentRun))
    {
        run      = lArgs.record();
        contract = this.parmReportContract().parmRdpContract() as ABSMRPAssessmentReportContract;
        if (contract)
        {
            contract.parmRunId(run.RunId);
        }
    }
}
